def minEatingSpeed(piles: list[int], h: int) -> int:
    import math
    lo, hi = 1, max(piles)
    ans = hi
    while lo <= hi:
        mid = (lo + hi) // 2
        hours = sum(math.ceil(p / mid) for p in piles)
        if hours <= h:
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans

